const WORLD = { minX: -760, maxX: 1810, minY: -750, maxY: 2230 };
const RIFT_GATE = { x: 1728, y: 953 };
const WORLD_CELL = 220;
const worldCell=(x,y,inRift=false)=>`${inRift?'rift':'city'}:${Math.floor(x/WORLD_CELL)}:${Math.floor(y/WORLD_CELL)}`;
const roomsAround=(x,y,inRift=false)=>{const cx=Math.floor(x/WORLD_CELL),cy=Math.floor(y/WORLD_CELL),rooms=[],prefix=inRift?'rift':'city';for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)rooms.push(`${prefix}:${cx+dx}:${cy+dy}`);return rooms};
const dbPath = process.env.DATABASE_PATH || join(root, 'data/lagos-life.sqlite');
