db.exec(`
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL COLLATE NOCASE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS players(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, avatar INTEGER NOT NULL DEFAULT 0, coins INTEGER NOT NULL DEFAULT 250, mood INTEGER NOT NULL DEFAULT 78, energy INTEGER NOT NULL DEFAULT 82, x REAL NOT NULL DEFAULT 508, y REAL NOT NULL DEFAULT 702, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS job_completions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,job_id TEXT NOT NULL,completed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS learning_completions(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,lesson_id TEXT NOT NULL,completed_at TEXT NOT NULL,PRIMARY KEY(user_id,lesson_id));
CREATE TABLE IF NOT EXISTS player_items(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,item_id TEXT NOT NULL,collected_at TEXT NOT NULL,PRIMARY KEY(user_id,item_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS visits(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, place_id TEXT NOT NULL, reward INTEGER NOT NULL, visited_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS homes(id TEXT PRIMARY KEY, name TEXT NOT NULL, district TEXT NOT NULL, emoji TEXT NOT NULL, x REAL NOT NULL, y REAL NOT NULL, price INTEGER NOT NULL, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS owned_homes(id INTEGER PRIMARY KEY AUTOINCREMENT, home_id TEXT NOT NULL UNIQUE REFERENCES homes(id), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, bought_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chat_messages(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, display_name TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL, room TEXT NOT NULL DEFAULT 'lagos', is_hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS chat_reports(id INTEGER PRIMARY KEY AUTOINCREMENT, message_id TEXT NOT NULL REFERENCES chat_messages(id) ON DELETE CASCADE, reporter_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, reason TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', resolved_by TEXT, resolved_at TEXT, UNIQUE(message_id,reporter_id));
CREATE INDEX IF NOT EXISTS idx_chat_created ON chat_messages(created_at DESC);
CREATE TABLE IF NOT EXISTS programming_resources(
 id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT,resource_type TEXT NOT NULL,
 languages TEXT NOT NULL,subjects TEXT NOT NULL,authors TEXT NOT NULL,source_repository TEXT NOT NULL,
 source_url TEXT NOT NULL,source_file TEXT,source_line INTEGER,catalog_license TEXT NOT NULL,
 content_license TEXT,notes TEXT NOT NULL,availability TEXT NOT NULL,difficulty TEXT,metadata TEXT NOT NULL,
 payload TEXT NOT NULL,imported_at TEXT NOT NULL,updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_resources_type_title ON programming_resources(resource_type,title COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS idx_resources_updated ON programming_resources(updated_at DESC);
CREATE TABLE IF NOT EXISTS player_resource_bookmarks(
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 resource_id TEXT NOT NULL REFERENCES programming_resources(id) ON DELETE CASCADE,
 saved_at TEXT NOT NULL,PRIMARY KEY(user_id,resource_id)
);
CREATE TABLE IF NOT EXISTS player_resource_history(
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 resource_id TEXT NOT NULL REFERENCES programming_resources(id) ON DELETE CASCADE,
 viewed_at TEXT NOT NULL,PRIMARY KEY(user_id,resource_id)
);
CREATE VIRTUAL TABLE IF NOT EXISTS programming_resources_fts USING fts5(
 title,authors,languages,subjects,description,
 content='programming_resources',content_rowid='rowid',tokenize='unicode61 remove_diacritics 2'
);
CREATE TRIGGER IF NOT EXISTS programming_resources_ai AFTER INSERT ON programming_resources BEGIN
 INSERT INTO programming_resources_fts(rowid,title,authors,languages,subjects,description)
 VALUES(new.rowid,new.title,new.authors,new.languages,new.subjects,coalesce(new.description,''));
END;
CREATE TRIGGER IF NOT EXISTS programming_resources_ad AFTER DELETE ON programming_resources BEGIN
 INSERT INTO programming_resources_fts(programming_resources_fts,rowid,title,authors,languages,subjects,description)
 VALUES('delete',old.rowid,old.title,old.authors,old.languages,old.subjects,coalesce(old.description,''));
END;
CREATE TRIGGER IF NOT EXISTS programming_resources_au AFTER UPDATE ON programming_resources BEGIN
 INSERT INTO programming_resources_fts(programming_resources_fts,rowid,title,authors,languages,subjects,description)
 VALUES('delete',old.rowid,old.title,old.authors,old.languages,old.subjects,coalesce(old.description,''));
 INSERT INTO programming_resources_fts(rowid,title,authors,languages,subjects,description)
 VALUES(new.rowid,new.title,new.authors,new.languages,new.subjects,coalesce(new.description,''));
END;
`);
db.exec(`CREATE TABLE IF NOT EXISTS coding_quest_completions(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,quest_id TEXT NOT NULL,code TEXT NOT NULL,completed_at TEXT NOT NULL,PRIMARY KEY(user_id,quest_id));CREATE TABLE IF NOT EXISTS github_links(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,github_id TEXT NOT NULL,login TEXT NOT NULL,avatar_url TEXT,encrypted_token TEXT NOT NULL,linked_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS github_oauth_states(state_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);CREATE TABLE IF NOT EXISTS learning_books(id TEXT PRIMARY KEY,title TEXT NOT NULL,language TEXT NOT NULL,description TEXT NOT NULL,price INTEGER NOT NULL,filename TEXT NOT NULL,added_by TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS learning_book_purchases(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,book_id TEXT NOT NULL REFERENCES learning_books(id) ON DELETE CASCADE,purchased_at TEXT NOT NULL,PRIMARY KEY(user_id,book_id));CREATE TABLE IF NOT EXISTS learning_videos(id TEXT PRIMARY KEY,title TEXT NOT NULL,language TEXT NOT NULL,description TEXT NOT NULL,youtube_url TEXT NOT NULL,added_by TEXT NOT NULL,created_at TEXT NOT NULL);`);
const libraryFiles=join(root,'data','learning-library');mkdirSync(libraryFiles,{recursive:true});
const upsertResource = db.prepare(`INSERT INTO programming_resources
 (id,title,description,resource_type,languages,subjects,authors,source_repository,source_url,source_file,source_line,catalog_license,content_license,notes,availability,difficulty,metadata,payload,imported_at,updated_at)
 VALUES (@id,@title,@description,@resourceType,@languages,@subjects,@authors,@sourceRepository,@sourceUrl,@sourceFile,@sourceLine,@catalogLicense,@contentLicense,@notes,@availability,@difficulty,@metadata,@payload,@now,@now)
 ON CONFLICT(id) DO UPDATE SET title=excluded.title,description=excluded.description,resource_type=excluded.resource_type,languages=excluded.languages,subjects=excluded.subjects,authors=excluded.authors,source_repository=excluded.source_repository,source_url=excluded.source_url,source_file=excluded.source_file,source_line=excluded.source_line,catalog_license=excluded.catalog_license,content_license=excluded.content_license,notes=excluded.notes,availability=excluded.availability,difficulty=excluded.difficulty,metadata=excluded.metadata,payload=excluded.payload,updated_at=excluded.updated_at
 WHERE programming_resources.payload<>excluded.payload`);
const importResourceBatch=db.transaction((resources:any[])=>{const now=new Date().toISOString();for(const resource of resources){const payload=JSON.stringify(resource);upsertResource.run({id:resource.id,title:resource.title,description:resource.description,resourceType:resource.resourceType,languages:JSON.stringify(resource.languages||[]),subjects:JSON.stringify(resource.subjects||[]),authors:JSON.stringify(resource.authors||[]),sourceRepository:resource.sourceRepository,sourceUrl:resource.sourceUrl,sourceFile:resource.sourceFile,sourceLine:resource.sourceLine,catalogLicense:resource.catalogLicense,contentLicense:resource.contentLicense,notes:JSON.stringify(resource.notes||[]),availability:resource.availability,difficulty:resource.difficulty,metadata:JSON.stringify(resource.metadata||{}),payload,now})}});
importResourceBatch(resourceCatalog);
