const sessionQuery = db.prepare(`SELECT s.user_id,u.username,u.display_name,p.avatar,p.coins,p.mood,p.energy,p.x,p.y,p.account_type AS accountType,p.job_id AS jobId,p.xp,p.learning_coins AS learningCoins,p.tasks_done AS tasksDone FROM sessions s JOIN users u ON u.id=s.user_id JOIN players p ON p.user_id=u.id WHERE s.token_hash=? AND s.expires_at>?`);
const playerQuery = db.prepare(`SELECT u.id,u.username,u.display_name AS name,p.avatar,p.coins,p.mood,p.energy,p.x,p.y,p.account_type AS accountType,p.job_id AS jobId,p.xp,p.learning_coins AS learningCoins,p.tasks_done AS tasksDone FROM users u JOIN players p ON p.user_id=u.id WHERE u.id=?`);
const publicPlayer = q => q && ({ id:q.id||q.user_id, username:q.username, name:q.name||q.display_name, avatar:q.avatar, accountType:q.accountType||'developer', coins:q.coins, learningCoins:q.learningCoins||0, mood:q.mood, energy:q.energy, x:q.x, y:q.y, heading:q.heading||0, inVehicle:!!q.inVehicle, inBuilding:!!q.inBuilding, inRift:!!q.inRift, jobId:q.jobId||'', xp:q.xp||0, tasksDone:q.tasksDone||0 });
app.use((req,_res,next)=>{try{req.cookies=cookie.parse(req.headers.cookie||'')}catch{req.cookies={}}const t=req.cookies[COOKIE];req.account=t?sessionQuery.get(hashToken(t),Date.now()):null;next()});
const auth=(req,res,next)=>req.account?next():res.status(401).json({error:'Sign in to continue.'});
const campus=(req,res,next)=>{if(!req.account)return res.status(401).json({error:'Sign in to continue.'});if(!db.prepare("SELECT 1 FROM learning_completions WHERE user_id=? AND lesson_id='orientation-trial'").get(req.account.user_id))return res.status(403).json({error:'Clear the Overview trial to unlock this learning room.'});next()};
const authLimit=rateLimit({windowMs:15*60*1000,limit:20,standardHeaders:true,legacyHeaders:false});
const scrypt:any=promisify(scryptCb as any);
async function passwordHash(password,salt=randomBytes(16).toString('hex')){const out=await scrypt(password,salt,64,{N:16384,r:8,p:1,maxmem:64*1024*1024});return `${salt}:${out.toString('hex')}`}
async function passwordMatches(password,stored){const [salt,hex]=stored.split(':');const expected=Buffer.from(hex||'','hex');const actual=await scrypt(password,salt,64,{N:16384,r:8,p:1,maxmem:64*1024*1024});return expected.length===actual.length&&timingSafeEqual(actual,expected)}
function issueSession(res,userId){const token=randomBytes(32).toString('base64url');db.prepare('INSERT INTO sessions VALUES(?,?,?,?)').run(hashToken(token),userId,Date.now()+SESSION_MS,stamp());res.cookie(COOKIE,token,{httpOnly:true,secure:prod,sameSite:'lax',path:'/',maxAge:SESSION_MS})}
const displayName=x=>typeof x==='string'?x.trim().replace(/[<>\u0000-\u001f]/g,'').slice(0,20):'';
const userSummary=(id,username,name)=>({id,username,name,isAdmin:!!process.env.ADMIN_USERNAME&&username.toLowerCase()===process.env.ADMIN_USERNAME.trim().toLowerCase()});
const githubKey=()=>{const value=process.env.GITHUB_TOKEN_ENCRYPTION_KEY||'';return /^[a-f0-9]{64}$/i.test(value)?Buffer.from(value,'hex'):null};
const encryptGithubToken=token=>{const key=githubKey();if(!key)throw new Error('GitHub encryption key is not configured.');const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',key,iv),body=Buffer.concat([cipher.update(token,'utf8'),cipher.final()]);return [iv.toString('hex'),cipher.getAuthTag().toString('hex'),body.toString('hex')].join(':')};
const decryptGithubToken=value=>{const key=githubKey();if(!key)throw new Error('GitHub encryption key is not configured.');const [iv,tag,body]=value.split(':'),d=createDecipheriv('aes-256-gcm',key,Buffer.from(iv,'hex'));d.setAuthTag(Buffer.from(tag,'hex'));return Buffer.concat([d.update(Buffer.from(body,'hex')),d.final()]).toString('utf8')};

