app.get('/api/inventory',auth,(req,res)=>res.json(db.prepare('SELECT item_id AS id,collected_at AS collectedAt FROM player_items WHERE user_id=? ORDER BY collected_at').all(req.account.user_id)));
app.post('/api/inventory/collect',auth,(req,res)=>{const item=items.find(x=>x.id===req.body?.itemId);if(!item)return res.status(404).json({error:'That collectible does not exist.'});const player=online.get(req.account.user_id)||playerQuery.get(req.account.user_id);if(Math.hypot(player.x-item.x,player.y-item.y)>42)return res.status(400).json({error:'Walk closer to the item before collecting it.'});const existing=db.prepare('SELECT 1 FROM player_items WHERE user_id=? AND item_id=?').get(req.account.user_id,item.id);if(existing)return res.json({item,already:true,player:publicPlayer(playerQuery.get(req.account.user_id)),inventory:db.prepare('SELECT item_id AS id,collected_at AS collectedAt FROM player_items WHERE user_id=? ORDER BY collected_at').all(req.account.user_id)});const collectedAt=stamp();db.transaction(()=>{db.prepare('INSERT INTO player_items(user_id,item_id,collected_at) VALUES(?,?,?)').run(req.account.user_id,item.id,collectedAt);db.prepare('UPDATE players SET coins=coins+?,xp=xp+?,updated_at=? WHERE user_id=?').run(item.reward,item.xp,collectedAt,req.account.user_id)})();const updated=publicPlayer(playerQuery.get(req.account.user_id));const live=online.get(req.account.user_id);if(live)Object.assign(live,updated);io.emit('player:update',updated);res.json({item,already:false,player:updated,inventory:db.prepare('SELECT item_id AS id,collected_at AS collectedAt FROM player_items WHERE user_id=? ORDER BY collected_at').all(req.account.user_id)})});
app.get('/api/homes',(_req,res)=>{const owners=db.prepare('SELECT home_id,user_id FROM owned_homes').all();res.json(homes.map(h=>({...h,ownerId:owners.find(o=>o.home_id===h.id)?.user_id||null,owned:owners.some(o=>o.home_id===h.id)})))});
app.get('/api/me',(req,res)=>{if(!req.account)return res.json({user:null,player:null,homes:[]});const p=publicPlayer(playerQuery.get(req.account.user_id));res.json({user:userSummary(p.id,p.username,p.name),player:p,homes:db.prepare('SELECT home_id AS id,bought_at AS boughtAt FROM owned_homes WHERE user_id=?').all(p.id)})});
app.post('/api/auth/signup',authLimit,async(req,res)=>{const username=typeof req.body?.username==='string'?req.body.username.trim().toLowerCase():'';const name=displayName(req.body?.displayName);const password=req.body?.password;const jobId=typeof req.body?.jobId==='string'?req.body.jobId:'';const accountType=['beginner','developer','grower'].includes(req.body?.accountType)?req.body.accountType:'developer';if(!/^[a-z0-9_]{3,18}$/.test(username))return res.status(400).json({error:'Username must be 3–18 letters, numbers or underscores.'});if(name.length<2)return res.status(400).json({error:'Display name must have at least 2 characters.'});if(typeof password!=='string'||password.length<10||password.length>128)return res.status(400).json({error:'Use a password between 10 and 128 characters.'});if(req.body?.adultConfirmed!==true)return res.status(400).json({error:'You must confirm you are 18 or older.'});if(!jobs.some(j=>j.id===jobId))return res.status(400).json({error:'Choose a developer career.'});if(db.prepare('SELECT 1 FROM users WHERE username=?').get(username))return res.status(409).json({error:'That username is already taken.'});try{const id=randomBytes(16).toString('hex'),pwd=await passwordHash(password),created=stamp();db.transaction(()=>{db.prepare('INSERT INTO users VALUES(?,?,?,?,?)').run(id,username,name,pwd,created);db.prepare('INSERT INTO players(user_id,job_id,account_type,updated_at) VALUES(?,?,?,?)').run(id,jobId,accountType,created)})();issueSession(res,id);const p=publicPlayer(playerQuery.get(id));res.status(201).json({user:userSummary(id,username,name),player:p,homes:[]})}catch(e){console.error(e);res.status(500).json({error:'Could not create account.'})}});
app.post('/api/auth/login',authLimit,async(req,res)=>{const username=typeof req.body?.username==='string'?req.body.username.trim().toLowerCase():'';const password=req.body?.password;if(typeof password!=='string'||password.length>128)return res.status(400).json({error:'Enter your username and password.'});const u=db.prepare('SELECT * FROM users WHERE username=?').get(username);const ok=u?await passwordMatches(password,u.password_hash):await passwordHash(password);if(!u||!ok)return res.status(401).json({error:'Username or password is incorrect.'});issueSession(res,u.id);const p=publicPlayer(playerQuery.get(u.id));res.json({user:userSummary(u.id,u.username,u.display_name),player:p,homes:db.prepare('SELECT home_id AS id,bought_at AS boughtAt FROM owned_homes WHERE user_id=?').all(u.id)})});
app.post('/api/auth/logout',auth,(req,res)=>{db.prepare('DELETE FROM sessions WHERE token_hash=?').run(hashToken(req.cookies[COOKIE]));res.clearCookie(COOKIE,{httpOnly:true,secure:prod,sameSite:'lax',path:'/'});res.json({ok:true})});
app.patch('/api/player',auth,(req,res)=>{const name=displayName(req.body?.name),avatar=Number(req.body?.avatar);if(name.length<2||!Number.isInteger(avatar)||avatar<0||avatar>5)return res.status(400).json({error:'Choose a valid name and avatar.'});db.prepare('UPDATE users SET display_name=? WHERE id=?').run(name,req.account.user_id);db.prepare('UPDATE players SET avatar=?,updated_at=? WHERE user_id=?').run(avatar,stamp(),req.account.user_id);const p=publicPlayer(playerQuery.get(req.account.user_id));io.emit('player:update',p);res.json({player:p})});
app.post('/api/jobs/select',auth,(req,res)=>{const job=jobs.find(x=>x.id===req.body?.jobId);if(!job)return res.status(404).json({error:'Choose a listed developer career.'});db.prepare('UPDATE players SET job_id=?,updated_at=? WHERE user_id=?').run(job.id,stamp(),req.account.user_id);const p=publicPlayer(playerQuery.get(req.account.user_id));io.emit('player:update',p);res.json({player:p,job})});
app.post('/api/jobs/complete',auth,(req,res)=>{const id=req.account.user_id,p=playerQuery.get(id),job=jobs.find(x=>x.id===p.jobId);if(!job)return res.status(400).json({error:'Pick a developer career first.'});if(Math.hypot(p.x-job.x,p.y-job.y)>145)return res.status(400).json({error:`Walk over to ${job.studio} to work.`});const last=db.prepare('SELECT completed_at AS completedAt FROM job_completions WHERE user_id=? ORDER BY id DESC LIMIT 1').get(id);if(last&&Date.now()-Date.parse(last.completedAt)<30000)return res.status(429).json({error:'Take a short break before starting the next task.'});const t=stamp();db.transaction(()=>{db.prepare('UPDATE players SET coins=coins+?,xp=xp+?,tasks_done=tasks_done+1,energy=MAX(8,energy-4),updated_at=? WHERE user_id=?').run(job.reward,job.reward,t,id);db.prepare('INSERT INTO job_completions(user_id,job_id,completed_at) VALUES(?,?,?)').run(id,job.id,t)})();const updated=publicPlayer(playerQuery.get(id));io.emit('player:update',updated);res.json({player:updated,reward:job.reward,task:job.task})});
app.post('/api/homes/:id/buy',auth,(req,res)=>{const h=homes.find(x=>x.id===req.params.id);if(!h)return res.status(404).json({error:'Home not found.'});const id=req.account.user_id;if(db.prepare('SELECT 1 FROM owned_homes WHERE home_id=?').get(h.id))return res.status(409).json({error:'This home already has an owner.'});const p=playerQuery.get(id);if(p.coins<h.price)return res.status(400).json({error:`You need ₦${h.price}.`});try{db.transaction(()=>{db.prepare('UPDATE players SET coins=coins-?,updated_at=? WHERE user_id=?').run(h.price,stamp(),id);db.prepare('INSERT INTO owned_homes(home_id,user_id,bought_at) VALUES(?,?,?)').run(h.id,id,stamp())})();const updated=publicPlayer(playerQuery.get(id));io.emit('player:update',updated);res.status(201).json({home:{...h,ownerId:id,owned:true},player:updated})}catch{res.status(409).json({error:'This home was just claimed by another player.'})}});
